insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'uf-deal-terms' and v.is_current), (select id from sources where slug = 'uf-nil-overview'), 'Deal guidance', 'Make sure every NIL deal spells out what you''ll do in return for payment (what posts, videos, appearances, etc.). Student-athletes must be compensated only for work actually performed.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
