insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'uf-own-merchandise'), 1, 'yes_with_conditions', 'Yes. Athletes may create and sell their own branded merchandise and autographed memorabilia. Using Florida Gators trademarks, logos or marks on it requires approval.', 'UF, Overview of Gators NIL', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
