insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'uf-logos-marks' and v.is_current), (select id from sources where slug = 'uf-licensing-faq'), 'Licensing FAQ', 'Anyone wishing to use the marks, logos and symbols of the University must obtain a license.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
