insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fsu-boosters'), 1, 'yes_with_conditions', 'FSU''s booster page sends boosters to its NIL site for rules on NIL activity with current athletes. It asks boosters with an existing relationship to a recruit to contact the Compliance Office.', 'The page lists general booster recruiting limits. It does not set a separate FSU booster NIL rule.', 'FSU Compliance page, Fans & Boosters', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'CHECK_FIRST', 'Boosters should check FSU''s NIL site and Compliance first.');
