insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fsu-agents' and v.is_current), (select id from sources where slug = 'fsu-t2'), 'Procedures, item 5', 'All non‐FSU registered agents must complete the registration within seven (7) business days of first contact.', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
