insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'miami-school-payments'), 1, 'yes', 'Miami''s athletic director wrote on July 1, 2025 that athletics departments can now share revenue directly with athletes. He said football, men''s and women''s basketball, baseball, soccer, volleyball, women''s tennis and women''s track and field will take part in revenue sharing for 2025-26.', 'Covers the 2025-26 school year only. It is a letter, not a policy document.', 'From the Desk of Dan Radakovich, July 1, 2025, ''House Settlement''', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'YES', 'Miami shares revenue with athletes in named sports.');
