insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fau-agents'), 1, 'yes_with_conditions', 'FAU says athletes may not hire a sports agent for pro athletic representation, only for marketing. FAU asks agents and NIL service providers to register with FAU before contacting an athlete. FAU''s registration form covers NIL service providers as well as agents. It says to return the form to the Compliance Office before contact with an athlete.', 'The first quote is from the list headed ''FAU Student-athletes MAY NOT''. The agents page dates from 2023 and names a person who is not on the current compliance staff list. The form names John Stephenson, who is not on the current staff directory. The form has a 2023 URL date.', 'FAU Student-Athlete Handbook 2026-27 and FAU Agents page; FAU Agent/Advisor Registration Application', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'DEPENDS', 'Marketing agents only, and they register with FAU.');
