insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fiu-school-logos-marks'), 1, 'only_with_approval', 'FIU says athletes may not use FIU trademarks or logos in NIL unless two FIU offices approve first. FIU also requires a written agreement and license or sponsorship fees. FIU''s handbook says FIU property, including logos and symbols, may not be used with an NIL opportunity without approval.', 'Adds to the existing rule. The handbook does not repeat who approves here. The policy names the two offices.', 'FIU Policy 910.001, Policy Statement; FIU 2026-2027 Student-Athlete Handbook, NIL section', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'CHECK_FIRST', 'FIU approval and a written agreement are needed.');
