insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, review_note, quick_status, short_answer) values ((select id from rules where slug = 'famu-disclosure-required'), 1, 'yes', 'FAMU says athletes should always report NIL deals to the FAMU Athletics Compliance Office. FAMU''s NIL question checklist tells athletes to make clear to a company that the athlete is obligated to report the deal to FAMU.', 'The page does not name a reporting system, form or deadline. The page is undated. The checklist is undated and does not name a system, form or deadline. It does not mention NIL Go. Published before the July 2025 rule changes or undated. Confirm with the school that it still applies.', 'FAMU Athletics Compliance page, Eligibility and Compliance; FAMU NIL Suggested Question Checklist, question VII', 'needs_verification', 'PENDING_INSTITUTION_CONFIRMATION', 'raw_source_text', 'The school published this before the July 2025 rule changes, or on an undated page. It has not been confirmed as current.', 'CHECK_FIRST', 'Report every NIL deal to FAMU Athletics Compliance.');
