insert into rules (slug, rule_topic_id, scope_type, institution_id, applies_to) values ('stetson-school-payments', (select id from rule_topics where slug = 'school-payments'), 'institution', (select id from institutions where slug = 'stetson-university'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'stetson-school-payments'), 1, 'yes_with_conditions', 'Stetson''s policy says the university, or an entity it owns, controls, funds or operates, may enter a written license or endorsement agreement for an athlete''s NIL. Stetson also announced it will opt in to the House settlement starting in 2026-27. Stetson''s policy says the university, or an entity it owns, controls, funds or operates, may sign a written license or endorsement agreement for an athlete''s NIL. It excludes agreements that pay for broadcast rights to games.', 'The policy limits the agreement to a period not to exceed the athlete''s period of eligibility.', 'Stetson University Name, Image, and Likeness Policy v.5, page 3; news release December 18, 2025; Stetson Name, Image, and Likeness Policy v.5, Policy (page 3)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'DEPENDS', 'Stetson may sign NIL agreements with athletes and opts in to House from 2026-27.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'stetson-school-payments' and v.is_current), (select id from sources where slug = 'stetson-s1'), 'Page 3, item a', 'Enter into a written license and/or endorsement agreement for the use of a student-athlete''s name, image or likeness, or other rights', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'stetson-school-payments' and v.is_current), (select id from sources where slug = 'stetson-s3'), 'First paragraph', 'Stetson University athletics will formally opt in to the NCAA House settlement beginning with the 2026–27 academic year', 'machine_raw_text', '2026-10-04', 'Claude (automated source research)');
