insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'stetson-contract-length'), 1, 'yes_with_conditions', 'Stetson''s policy says a school agreement for an athlete''s NIL may not run longer than the athlete''s period of eligibility. If both agree, content made while the athlete is enrolled may keep being used after eligibility ends.', 'Applies to agreements between Stetson and the athlete.', 'Stetson University Name, Image, and Likeness Policy v.5, page 3, item a', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'DEPENDS', 'School NIL agreements end with eligibility, with one content exception.');
