insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'stetson-nil-allowed'), 1, 'yes_with_conditions', 'Stetson''s policy says an athlete may use their name, image and likeness to promote athletic and non-athletic business activities. It gives products, services, camps and clinics, and personal appearances as examples.', NULL, 'Stetson Name, Image, and Likeness Policy v.5, Policy', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'YES', 'Yes, for real business activities.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'stetson-nil-allowed' and v.is_current), (select id from sources where slug = 'stetson-t1'), 'Policy, paragraph 1 (page 2)', 'may use their name, image, and likeness (“NIL”) to promote their athletically and non-athletically related business activities (e.g., products, services, camps & clinics, personal appearances)', 'visual_source_check', '2026-10-04', 'Claude (automated source research)');
