insert into rules (slug, rule_topic_id, scope_type, institution_id, applies_to) values ('stetson-deal-terms', (select id from rule_topics where slug = 'deal-terms'), 'institution', (select id from institutions where slug = 'stetson-university'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'stetson-deal-terms'), 1, 'yes_with_conditions', 'Stetson''s policy says NIL pay must be for a valid business purpose. It says rates and terms must match what similar people with similar NIL value are paid. Stetson''s policy warns that Pell Grant or need based aid could be affected by NIL pay and sends questions to the Office of Student Financial Planning. It says earned income must be reported on the athlete''s tax return.', NULL, 'Stetson Name, Image, and Likeness Policy v.5, Policy; Stetson Name, Image, and Likeness Policy v.5, Procedures (page 5)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'DEPENDS', 'Pay must match a real business purpose and market rates.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'stetson-deal-terms' and v.is_current), (select id from sources where slug = 'stetson-t1'), 'Policy, paragraph 1 (page 2)', 'such compensation is for a valid business purpose with compensation at rates and terms commensurate with compensation paid to similarly situated individuals with comparable name, image and likeness value', 'visual_source_check', '2026-10-04', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'stetson-deal-terms' and v.is_current), (select id from sources where slug = 'stetson-t1'), 'Procedures (page 5)', 'Pell Grant or need based financial aid could be impacted based on compensation from Name, Image and Likeness.', 'visual_source_check', '2026-10-04', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'stetson-deal-terms' and v.is_current), (select id from sources where slug = 'stetson-t1'), 'Procedures (page 5)', 'Earned income will need to be reported on the student-athlete’s annual tax return.', 'visual_source_check', '2026-10-04', 'Claude (automated source research)');
