insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-am-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: The PDF file''s author field reads ''Rica Calhoun''. This is file metadata, not a printed byline, so it is not recorded as a contact.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-am-university'), NULL, NULL, 'ambiguity', 'October 4 correction: not_found: ''A FAMU statement of its own that it opted in to the House settlement or revenue sharing'' is partly outdated. FAMU published a June 8, 2025 statement on the House settlement and a July 9, 2026 release that names revenue sharing. Neither uses the words opt in.');
