insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'left_off_page', 'JU says financial aid questions tied to NIL pay should go to Jacksonville University Student Financial Services, because Pell Grant or need-based aid could be affected. Reason: A financial aid referral, not a parent or guardian rule. Left off the page.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'claim', 'JU''s NIL page dates from 2022 and has not been updated for the House settlement. Every JU rule here needs a human check before it is shown as current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'claim', 'JU requires written approval from its Office of Marketing and Communications before athletes use JU logos or word marks.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'claim', 'JU bars NIL deals with gambling, sports wagering, nutritional supplement and banned-substance companies.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'claim', 'JU names INFLCR as its disclosure tool and asks for copies of signed agreements.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'claim', 'JU tells international athletes not to sign any NIL deal without guidance from JU International Student Services.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'claim', 'No official JU statement on House settlement opt-in was found. Only a secondary tracker lists JU as opted in.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'ambiguity', 'The JU NIL page is dated May 9, 2022 by its URL. It cites Florida Statute 1006.74 and May 10, 2022 NCAA guidance, both from before the House settlement. It is still the NIL page linked in the Compliance menu.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'ambiguity', 'The page says ''Neither JU nor JU staff members may compensate or arrange compensation'' for NIL and that staff ''cannot facilitate NIL conversations or arrangements''. These lines reflect pre-House rules and are not recorded as current rules.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'ambiguity', 'The page says NIL pay ''must be within fair market value'' without saying who checks this.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'ambiguity', 'The NIL page lists Daniel Calderon as Compliance Coordinator. The staff directory lists him as Director of Compliance. The directory title is used.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'ambiguity', 'The NIL page also lists Rick Canter (Deputy AD) and Dee Brown (Senior Associate AD for University & Athletics Relations) as resources. Their current roles were not confirmed in the directory, so they are not recorded as contacts.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'ambiguity', 'The INFLCR link on the page was captured through a summarising tool as https://dash.inflcr.com/. Whether JU still uses INFLCR is not confirmed.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'ambiguity', 'The JU Current Student Athletes page (read by extraction) also mentions JumpForward for forms.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'ambiguity', 'October 4 re-check: Checked today: JU NIL page (unchanged, no House, revenue, NIL Go, 2025 or 2026 text), Compliance hub, Current Student-Athletes, Boosters & Fans, and the judolphins.com news archive for Name, Image; revenue sharing; House settlement; NIL Go; settlement; INFLCR; collective.');
