insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-north-florida'), NULL, NULL, 'claim', 'UNF bans NIL deals with gambling/sports wagering, alcohol, tobacco, marijuana, controlled substances, CBD, adult entertainment and vendors tied to NCAA banned substances.');
